    /// Whether an active state fills this icon: the selected
    /// navigation item, a toggled control.
    pub const fn has_fill(self) -> bool {
        matches!(
            self,
            Self::Home
                | Self::Dashboard
                | Self::Settings
                | Self::Lock
                | Self::Bookmark
                | Self::Star
                | Self::PushPin
                | Self::CheckCircle
                | Self::Schedule
                | Self::Flag
                | Self::Notifications
                | Self::Person
                | Self::Group
                | Self::Groups
                | Self::AccountCircle
                | Self::Mail
                | Self::Chat
                | Self::Work
                | Self::ReceiptLong
                | Self::Payments
                | Self::AccountBalance
                | Self::Description
                | Self::Folder
                | Self::Inventory2
                | Self::CalendarMonth
                | Self::Analytics
                | Self::Route
                | Self::Lightbulb
                | Self::Explore
        )
    }

